~~~ts
type State = {kind:"loading"} | {kind:"error";message:string} | {kind:"success";items:string[]};
function summary(state: State): string {
  if (state.kind === "success") return String(state.items.length);
  if (state.kind === "error") return state.message;
  return "Loading";
}
~~~
items is available in the success branch because the discriminant establishes the member.

