~~~js
function parseTicketId(raw) {
  if (!/^[1-9][0-9]*$/.test(raw)) return null;
  const id = Number(raw);
  return Number.isSafeInteger(id) && id <= 1000000 ? id : null;
}
~~~
The entire string must match the allowed representation before conversion is accepted.

~~~ts
function readTitle(value: unknown) {
  if (typeof value !== "string") return {ok:false,code:"type"};
  const title = value.trim();
  if (!title) return {ok:false,code:"required"};
  if (title.length > 120) return {ok:false,code:"too_long"};
  return {ok:true,title};
}
~~~
The returned success value is the result of executed checks, not an assertion about untrusted input.

